import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M0 14a2 2 0 1 1 4 0 2 2 0 0 1-4 0M11 0a1 1 0 0 0-1 1v2.768L7.603 2.384a1 1 0 1 0-1 1.732L9 5.5 6.603 6.884a1 1 0 0 0 1 1.732L10 7.232V10a1 1 0 1 0 2 0V7.232l2.397 1.384a1 1 0 1 0 1-1.732L13 5.5l2.397-1.384a1 1 0 1 0-1-1.732L12 3.768V1a1 1 0 0 0-1-1"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M0 17.5a2.5 2.5 0 1 1 5 0 2.5 2.5 0 0 1-5 0M14 0a1 1 0 0 0-1 1v3.768L9.737 2.884a1 1 0 1 0-1 1.732L12 6.5 8.737 8.384a1 1 0 0 0 1 1.732L13 8.232V12a1 1 0 1 0 2 0V8.232l3.263 1.884a1 1 0 0 0 1-1.732L16 6.5l3.263-1.884a1 1 0 1 0-1-1.732L15 4.768V1a1 1 0 0 0-1-1"] as readonly string[];

export const RegexIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="regex" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
RegexIcon.displayName = `Blueprint6.Icon.RegexIcon`;

/**
 * @deprecated Use {@link RegexIcon} instead.
 */
export const Regex: typeof RegexIcon = RegexIcon;

export default RegexIcon;
